The identity element of max (join) is the least element (bottom) of the input array's dtype.
The identity element of min (meet) is the greatest element (top) of the input array's dtype.
Therefore, the max and min of an empty array should be the least and greatest element of its dtype, respectively.
This can be implemented by editing jax._src.numpy.reductions.
Example implementation:
from jax import numpy as jnp


def min_value(dtype):
    try:
        return jnp.iinfo(dtype).min
    except ValueError:
        pass

    try:
        return jnp.finfo(dtype).min
    except ValueError:
        pass

    if dtype == bool:
        return False


def max_value(dtype):
    try:
        return jnp.iinfo(dtype).max
    except ValueError:
        pass

    try:
        return jnp.finfo(dtype).max
    except ValueError:
        pass

    if dtype == bool:
        return True


def safe_max(a, initial=None):
    if initial is None:
        initial = min_value(a.dtype)
    return a.max(initial=initial)


def safe_min(a, initial=None):
    if initial is None:
        initial = max_value(a.dtype)
    return a.min(initial=initial)


def main():
    for dtype in [bool, jnp.uint8, jnp.float32, jnp.int32]:
        empty = jnp.array([], dtype)
        assert empty.sum() == 0
        assert empty.prod() == 1

        try:
            assert empty.max() == min_value(empty.dtype)
        except ValueError as exception:
            print(repr(exception))

        try:
            assert empty.min() == max_value(empty.dtype)
        except ValueError as exception:
            print(repr(exception))

        assert safe_max(empty) == min_value(empty.dtype)
        assert safe_min(empty) == max_value(empty.dtype)


if __name__ == "__main__":
    main()
